    if (match.index > lastIndex) {
      nodes.push(text.substring(lastIndex, match.index));
    }

    const [, , mathExpr, isLinkOrImg, linkText, linkUrl, , codeText, , boldText, , italicTextStar, italicTextUnder, , strikeText] =
      match;

