export type SwitchShape = 'pill' | 'rectangle' | 'rounded';

export interface SwitchProps
  extends Omit<React.InputHTMLAttributes<HTMLInputElement>, 'size'> {
  label?: string;
  description?: string;
  sizeVariant?: 'sm' | 'md' | 'lg';
  shape?: SwitchShape;
}

